    {
        OUString aPath;
        if (!rItemVector.empty())
            aPath = rItemVector.at(0);
        return uno::Any(aPath);
    }
    else
    {
        // convert to sequence
        return uno::Any(comphelper::containerToSequence(rItemVector));
    }
